/*
 * node_modules/mochinet — node:net-shaped shim on top of mochinode_net.dll.
 *
 * Client side is real: connect() opens a TCP socket via the native
 * tcpConnect export (non-blocking connect + 5s bounded select), write() sends,
 * end() flushes + closes. Data is pumped to 'data' events by a cooperative
 * 10ms poll loop (the engine is single-threaded; the native recv is
 * non-blocking). Server side (createServer) stays MOCHI_UNSUPPORTED — the
 * HTTP server lives in node_modules/net (createServer over httpAccept).
 */

import { EventEmitter } from '../mochievents/index.js';
import { loadNative } from '../mochinode/index.js';
import { setTimeout as osSetTimeout, clearTimeout as osClearTimeout } from 'mbjs:os';

let native = null;
try { native = await loadNative('mochinode_net.dll'); }
catch (e) { native = null; }

function unsupported(name) {
    const err = new Error(`mochinet: ${name} is unavailable on MochiBerry runtime`);
    err.code = 'MOCHI_UNSUPPORTED';
    return err;
}

export class Socket extends EventEmitter {
    constructor() {
        super();
        this.connecting = false;
        this.destroyed = true;
        this.readable = false;
        this.writable = false;
        this.remoteAddress = null;
        this.remotePort = null;
        this._fd = -1;
        this._timer = null;
        this._bytesRead = 0;
        this._bytesWritten = 0;
    }

    connect(port, host, cb) {
        if (typeof host === 'function') { cb = host; host = '127.0.0.1'; }
        host = host || '127.0.0.1';
        if (typeof cb === 'function') this.once('connect', cb);
        if (!native) {
            queueMicrotask(() => this.emit('error', unsupported('net.connect (native missing)')));
            return this;
        }
        this.connecting = true;
        try {
            const fd = native.tcpConnect(String(host), Number(port));
            if (fd < 0) {
                queueMicrotask(() => this.emit('error', new Error('mochinet: connect to ' + host + ':' + port + ' failed')));
                return this;
            }
            this._fd = fd;
            this.connecting = false;
            this.destroyed = false;
            this.readable = true;
            this.writable = true;
            this.remoteAddress = host;
            this.remotePort = port;
            this.emit('connect');
            this._startPolling();
        } catch (e) {
            queueMicrotask(() => this.emit('error', e));
        }
        return this;
    }

    _startPolling() {
        const poll = () => {
            if (this.destroyed || this._fd < 0) return;
            let chunk = null;
            try { chunk = native.httpRead(this._fd, 16384); }
            catch (e) { this.destroy(); return; }
            if (chunk !== undefined && chunk !== null && chunk !== '') {
                const s = String(chunk);
                this._bytesRead += s.length;
                const bytes = new Uint8Array(s.length);
                for (let i = 0; i < s.length; i++) bytes[i] = s.charCodeAt(i) & 0xff;
                this.emit('data', bytes);
            }
            this._timer = osSetTimeout(poll, 10);
        };
        this._timer = osSetTimeout(poll, 10);
    }

    _writeData(data) {
        if (this.destroyed || this._fd < 0) return 0;
        const s = typeof data === 'string' ? data
            : (data instanceof Uint8Array ? Array.from(data, (b) => String.fromCharCode(b)).join('') : String(data));
        try {
            const n = native.httpWrite(this._fd, s);
            if (n > 0) this._bytesWritten += Number(n);
            return n;
        } catch (e) { return 0; }
    }

    write(data, cb) {
        const n = this._writeData(data);
        if (typeof cb === 'function') queueMicrotask(cb);
        return n !== 0;
    }

    end(data, cb) {
        if (data !== undefined && data !== null) this._writeData(data);
        if (this._timer) { osClearTimeout(this._timer); this._timer = null; }
        if (this._fd >= 0) {
            try { native.httpClose(this._fd); } catch (e) {}
            this._fd = -1;
        }
        this.readable = false;
        this.writable = false;
        this.emit('end');
        this.emit('close');
        this.destroyed = true;
        if (typeof cb === 'function') queueMicrotask(cb);
        return this;
    }

    destroy(error) {
        if (this._timer) { osClearTimeout(this._timer); this._timer = null; }
        if (this._fd >= 0) {
            try { native.httpClose(this._fd); } catch (e) {}
            this._fd = -1;
        }
        this.readable = false;
        this.writable = false;
        this.destroyed = true;
        if (error) this.emit('error', error);
        this.emit('close');
        return this;
    }

    setTimeout() { return this; }
    setNoDelay() { return this; }
    setKeepAlive() { return this; }
}

export function createConnection(options, cb) {
    const sock = new Socket();
    if (typeof options === 'object' && options !== null) {
        const port = options.port;
        const host = options.host || '127.0.0.1';
        sock.connect(port, host, cb);
    } else {
        sock.connect(options, cb);
    }
    return sock;
}
export function connect(options, cb) { return createConnection(options, cb); }
export function createServer() { throw unsupported('net.createServer'); }
export function isIP(input) {
    const s = String(input || '');
    if (/^\d{1,3}(\.\d{1,3}){3}$/.test(s)) return 4;
    if (s.includes(':')) return 6;
    return 0;
}
export const isIPv4 = (input) => isIP(input) === 4;
export const isIPv6 = (input) => isIP(input) === 6;
export default { Socket, createConnection, connect, createServer, isIP, isIPv4, isIPv6 };
